	return ans;
}
int makeQ(long long y)
{
	cout<<"Q "<<y<<endl;
	int ans=0;
	cin>>ans;
	return ans;
}
int query(long long x)
{
	int res=makeQ(x);
	for(long long w:s)
	if(w>=x)
	 res--;
	return res;
}
long long guess(int n)
{
	long long pre=0;
	for(int i=n-1;i>=0;i--)
	if(query(pre|(1ll<<i))>0)
	{
		pre|=(1ll<<i);
	}
	return pre;
}
